public static void swap( int[] a,
int i, int j) {
  int tmp = a[i];
  a[i] = a[j];
  a[j] = tmp;
}


public static void sort( int[] list,
int start, int stop ){
  if(start >= stop)
    <*1>;

  int p = (start + stop) / 2;

  swap(list, p, start);
  int pVal = list[start];

  int i, j = start;

  for(i = start + 1; i <= stop; i++ ){
    if( list[i] <= pVal){
      j++;
      swap(list, i, j);
    }
  }

  if(start == 0 && stop == list.length - 1)
    for(int v : list)
      System.out.print(v);

  swap(list, start, j);
  sort( list, start, j - 1 );
  sort( list, j + 1, stop );
}


public static void sample(){
  int[] data = {6, 0, 3, 4, 7, 8, -1};
  sort(data, 0, 6);
}

